    # ---- MS-10 payment mock: /process (charge), /capture, /refund -> Transaction ----
    python3 - "$PAYMENT_URL" <<'PYPAY' &
import sys, json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse
port = int(sys.argv[1].rsplit(":", 1)[-1])
class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _send(self, code, body):
        p = json.dumps(body).encode()
        self.send_response(code); self.send_header("Content-Type","application/json")
        self.send_header("Content-Length", str(len(p))); self.end_headers(); self.wfile.write(p)
    def do_POST(self):
        path = urlparse(self.path).path
        length = int(self.headers.get("Content-Length", 0) or 0)
        raw = self.rfile.read(length) if length else b"{}"
        try: req = json.loads(raw or b"{}")
        except Exception: req = {}
        amt = req.get("amount", 130.375)
        if path.endswith("/payments/process"):
            # Charge declined path for the sentinel amount (checkout 402 test).
            if str(amt) == "1" or amt == 1:
                return self._send(402, {"error": "payment_required", "message": "charge declined"})
            return self._send(200, {"transaction_id": "TX-9001", "order_id": req.get("order_id"),
                "amount": amt, "currency": "USD", "transaction_type": "AuthorizeCapture",
                "payment_type": req.get("payment_type", "CreditCard"),
                "event_published": "payment.captured", "persisted": True, "partial": False})
        if path.endswith("/capture"):
            return self._send(200, {"transaction_id": "TX-9002", "amount": amt, "currency": "USD",
                "transaction_type": "Capture", "event_published": "payment.captured", "persisted": True})
        if path.endswith("/refund"):
            return self._send(200, {"transaction_id": "TX-9004", "amount": amt, "currency": "USD",
                "transaction_type": "Refund", "event_published": "payment.refunded", "persisted": True})
        return self._send(404, {"error": "not_found", "message": "unknown"})
HTTPServer(("127.0.0.1", port), H).serve_forever()
PYPAY
