# ============================================
# Helper Functions
# ============================================

# Extract a top-level field from JSON response (handles nested objects, UUIDs, string IDs).
# NEVER use grep for ID extraction — nested objects may serialize before the root id.
extract_field() {
    local json=$1
    local field=$2
    if command -v jq &>/dev/null; then
        echo "$json" | jq -r ".$field"
    else
        echo "$json" | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get('$field',''))"
    fi
}

assert_status() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7
    local extra_header=$8

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    # Sentinel __NOSTORE__ exercises the missing-required-x-store-id boundary (400).
    local store_hdr_opt=(-H "$STORE_HEADER")
    if [ "$extra_header" = "__NOSTORE__" ]; then
        store_hdr_opt=()
        extra_header=""
    fi

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        actual_status=$(curl -s -o /dev/null -w '%{http_code}' -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" "${store_hdr_opt[@]}" ${extra_header:+-H "$extra_header"} -d "$payload")
    else
        actual_status=$(curl -s -o /dev/null -w '%{http_code}' -X "$http_method" "$url" \
            -H "$TENANT_HEADER" "${store_hdr_opt[@]}" ${extra_header:+-H "$extra_header"})
    fi

    if [ "$actual_status" = "$expected_status" ]; then
        echo -e "  ${GREEN}✅ PASSED${NC} (HTTP $actual_status)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC} (Expected: $expected_status, Got: $actual_status)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $actual_status")
        return 1
    fi
}

# assert_json_field — presence / value pattern (fixed-string grep; use for money values, NOT regex).
assert_json_field() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local json_pattern=$7
    local extra_header=$8

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected pattern: $json_pattern"

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        result=$(curl -s -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" -H "$STORE_HEADER" ${extra_header:+-H "$extra_header"} -d "$payload")
    else
        result=$(curl -s -X "$http_method" "$url" -H "$TENANT_HEADER" -H "$STORE_HEADER" ${extra_header:+-H "$extra_header"})
    fi

    if echo "$result" | grep -qF "$json_pattern"; then
        echo -e "  ${GREEN}✅ PASSED${NC}"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC}"
        echo "  Expected pattern: $json_pattern"
        echo "  Got: $(echo "$result" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Pattern '$json_pattern' not found")
        return 1
    fi
}

# assert_json_absent — assert a substring is NOT present (used for the full-PAN PCI check, BR-ORD-020).
assert_json_absent() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local forbidden=$7

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Forbidden substring: $forbidden"

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        result=$(curl -s -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" -H "$STORE_HEADER" -d "$payload")
    else
        result=$(curl -s -X "$http_method" "$url" -H "$TENANT_HEADER" -H "$STORE_HEADER")
    fi

    if echo "$result" | grep -q "$forbidden"; then
        echo -e "  ${RED}❌ FAILED${NC} (forbidden substring present)"
        echo "  Got: $(echo "$result" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Forbidden '$forbidden' WAS present")
        return 1
    else
        echo -e "  ${GREEN}✅ PASSED${NC} (forbidden substring absent)"
        PASSED=$((PASSED + 1))
        return 0
    fi
}

# Capture BOTH status code AND response body in a single request.
# Sets global variables: LAST_STATUS and LAST_BODY. Optional 4th arg = extra header.
capture_with_status() {
    local http_method=$1
    local url=$2
    local payload=$3
    local extra_header=$4
    local response

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" -H "$STORE_HEADER" ${extra_header:+-H "$extra_header"} -d "$payload")
    else
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H "$TENANT_HEADER" -H "$STORE_HEADER" ${extra_header:+-H "$extra_header"})
    fi

    LAST_STATUS=$(echo "$response" | tail -1)
    LAST_BODY=$(echo "$response" | sed '$d')
}

# Assert status + capture body in one call (prevents double-POST problem).
# Optional 8th arg = extra header (e.g. idempotency-key, or an alternate store header).
assert_status_and_capture() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7
    local extra_header=$8

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    capture_with_status "$http_method" "$url" "$payload" "$extra_header"

    if [ "$LAST_STATUS" = "$expected_status" ]; then
        echo -e "  ${GREEN}✅ PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC} (Expected: $expected_status, Got: $LAST_STATUS)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $LAST_STATUS")
        return 1
    fi
}

# Assert on an already-captured body (use after assert_status_and_capture on the SAME response).
assert_captured_field() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local body=$4
    local json_pattern=$5

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected pattern: $json_pattern"

    if echo "$body" | grep -qF "$json_pattern"; then
        echo -e "  ${GREEN}✅ PASSED${NC}"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC}"
        echo "  Expected pattern: $json_pattern"
        echo "  Got: $(echo "$body" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Pattern '$json_pattern' not found in captured body")
        return 1
    fi
}

