assert_status 72 "INV-ORD-004: off-enum status rejected (422)" "BR-ORD-029" \
    "PATCH" "$API_URL/$ORDER_ID/status" \
    '{"status":"Banana"}' \
    "422"
assert_json_field 73 "INV-ORD-004: order status unchanged after illegal value (still Delivered)" "BR-ORD-029" \
    "GET" "$API_URL/$ORDER_ID" "null" \
    '"status":"Delivered"'

# ============================================================================
# SECTION 6: Refund + Async Settlement Effect (BR-ORD-030; INV-ORD-005/007)
#   BV-2 — settlement applied by CONSUMING payment.refunded; asserted through the order read.
# ============================================================================
echo ""
echo -e "${CYAN}══════════════════════════════════════════════════${NC}"
echo -e "${CYAN}SECTION 6: Refund + Async Settlement (BR-ORD-030; INV-ORD-005/007)${NC}"
echo -e "${CYAN}══════════════════════════════════════════════════${NC}"

# Place a fresh order to refund (Delivered order above is fine, but use a clean one for refund math).
REFUND_ORDER_BODY="{\"cart_code\":\"CART-1\",\"idempotency_key\":\"chk-refund\",\"customer\":{\"billing\":$BILLING_OK},\"payment\":{\"payment_type\":\"CreditCard\",\"number\":\"4111111111111111\",\"holder\":\"J Doe\",\"cvv\":\"123\",\"expiry_month\":12,\"expiry_year\":2028,\"card_type\":\"Visa\"},\"items\":[{\"sku\":\"prod-10\",\"unit_price\":49.95,\"quantity\":2}]}"
assert_status_and_capture 74 "Place order for refund tests" "BR-ORD-030" \
    "POST" "$API_URL/" "$REFUND_ORDER_BODY" "201" "idempotency-key: chk-refund"
REFUND_ORDER_ID=$(extract_field "$LAST_BODY" "order_id")

# BR-ORD-030: admin refund delegates to payment; order responds 202 Accepted (settlement via event).
assert_status_and_capture 75 "Admin refund accepted (202; settlement via payment.refunded)" "BR-ORD-030" \
    "POST" "$API_URL/$REFUND_ORDER_ID/refund" '{"amount":50.00}' "202"
assert_captured_field 76 "Refund acknowledgement echoes refund_requested 50.00" "BR-ORD-030" \
    "$LAST_BODY" '"refund_requested":50'

# BR-ORD-030 error (INV-ORD-005): refund exceeding the order total rejected (422).
assert_status 77 "INV-ORD-005: refund exceeding order total rejected (422)" "BR-ORD-030" \
    "POST" "$API_URL/$REFUND_ORDER_ID/refund" '{"amount":9999.00}' "422"
# BR-ORD-030 error: zero / non-positive refund rejected (422).
assert_status 78 "Refund of non-positive amount rejected (422)" "BR-ORD-030" \
    "POST" "$API_URL/$REFUND_ORDER_ID/refund" '{"amount":0}' "422"

# INV-ORD-007 (behavioral, idempotent settlement): a duplicate refund of the SAME amount does not
#   double-apply — cumulative refund stays within the total, and the read-back total is unchanged
#   between the two identical requests (settlement applied AT MOST ONCE per transaction).
assert_status_and_capture 79 "Read order total before repeated settlement" "BR-ORD-030" \
    "GET" "$API_URL/$REFUND_ORDER_ID" "null" "200"
TOTAL_BEFORE=$(extract_field "$LAST_BODY" "total")
# Re-issue the identical refund request (same amount) — the idempotent consumer must not double-decrement.
assert_status 80 "INV-ORD-007: repeated identical refund still bounded (<= total, 202/422)" "BR-ORD-030" \
    "POST" "$API_URL/$REFUND_ORDER_ID/refund" '{"amount":50.00}' "202"
assert_status_and_capture 81 "INV-ORD-005/007: cumulative refund never exceeds order total after replay" "BR-ORD-030" \
    "GET" "$API_URL/$REFUND_ORDER_ID" "null" "200"
assert_captured_field 82 "Order still readable with a bounded total after replay (idempotent settlement)" "BR-ORD-030" \
    "$LAST_BODY" '"total"'

