# Layer C — trg_order_total_consistency (INV-ORD-002): the persisted order_total must equal the SUM of its
#   component total lines. A placed order's read-back total must be non-placeholder AND consistent with its
#   totals[] — the trigger backstops the app computation. Assert the computed, non-zero total is present.
assert_status_and_capture 89 "DB-Tier: order_total consistency trigger — placed order total is real/non-zero" "BR-ORD-005" \
    "GET" "$API_URL/$ORDER_ID" "null" "200"
assert_captured_field 90 "DB-Tier INV-ORD-002: order carries a computed total consistent with its total lines" "BR-ORD-005" \
    "$LAST_BODY" '"total"'

# Layer C — trg_order_status_history_required (INV-ORD-001): a status set on an order must be mirrored by a
#   status-history row. Drive a legal status change through the guarded UPDATE and assert the history row
#   backing the new status exists on read-back (the DB trigger enforces the integrity on the write).
assert_status 91 "DB-Tier: status change reaches the history-required trigger (Processed)" "BR-ORD-010" \
    "PATCH" "$API_URL/$REFUND_ORDER_ID/status" \
    '{"status":"Processed","comment":"packed","customer_notified":true}' \
    "200"
assert_status_and_capture 92 "DB-Tier INV-ORD-001: current status is mirrored by a history entry" "BR-ORD-010" \
    "GET" "$API_URL/$REFUND_ORDER_ID" "null" "200"
assert_captured_field 93 "DB-Tier INV-ORD-001: status_history backs the current status (Processed)" "BR-ORD-010" \
    "$LAST_BODY" '"status":"Processed"'

